/**
 * Wires `DdxErrorPagePlugin` onto every Scramjet frame.
 *
 * Registration order matters: this must be installed AFTER the downloads
 * subsystem so the download plugin (which may consume the response body)
 * runs first. The error plugin only reads `response.status`, so it never
 * competes for the body.
 *
 * Rendering uses `iframe.srcdoc` — no second navigation, no URL params,
 * and the full structured context survives intact.
 */

import {
  DdxErrorPagePlugin,
  type ErrorPageContext,
  type ErrorPluginFrameLike,
} from './errorPlugin';

interface ControllerLike {
  createFrame?: (...args: unknown[]) => unknown;
  frames?: Array<unknown>;
}

interface FrameWithElement {
  element?: HTMLIFrameElement;
  hooks?: { fetch?: { preresponse?: unknown; error?: unknown } };
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const ERROR_TYPE_LABELS: Record<ErrorPageContext['errorType'], string> = {
  dns: 'Address not found',
  timeout: 'Connection timed out',
  proxy: 'Proxy error',
  http_error: 'Server error',
  blocked: 'Request blocked',
  unknown: 'Unexpected error',
};

/**
 * Build the standalone error document. Critical CSS is inlined so the
 * document renders correctly inside `srcdoc`, where relative asset URLs
 * would not resolve.
 */
export function buildErrorDocument(context: ErrorPageContext): string {
  const heading = ERROR_TYPE_LABELS[context.errorType] ?? ERROR_TYPE_LABELS.unknown;
  const logoDataUri = 'data:image/png;base64,';
  const detailLines = [
    context.status ? `Status: ${context.status} ${context.statusText}`.trim() : '',
    context.originalUrl ? `URL: ${context.originalUrl}` : '',
    `Request ID: ${context.requestId}`,
    `Timestamp: ${new Date(context.timestamp).toISOString()}`,
    context.message ? `Error: ${context.message}` : '',
  ].filter(Boolean).join('\n');
  const css = `
    :root {
      --main: rgba(199,125,255,1);
      --bg-1: rgba(10,10,10,1);
      --bg-2: rgba(12,12,12,1);
      --text: rgba(178,178,178,1);
      --proto: color-mix(in oklab, var(--text) 70%, var(--bg-2));
      --white-05: color-mix(in oklab, var(--text) 5%, transparent);
      --white-08: color-mix(in oklab, var(--text) 8%, transparent);
      --white-10: color-mix(in oklab, var(--text) 10%, transparent);
      --shadow-outer: color-mix(in oklab, #000 30%, transparent);
    }
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    * { font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
    html, body { height: 100vh; width: 100vw; background: var(--bg-2); color: var(--text); overflow-x: hidden; }
    main { max-width: 80rem; margin: 0 auto; padding: 7rem 1rem 6rem; }
    .hero { display: flex; align-items: center; justify-content: center; margin-bottom: 2.5rem; }
    .hero-badge { backdrop-filter: blur(8px); display: inline-flex; align-items: center; gap: 0.5rem; border-radius: 1rem; border: 1px solid var(--white-10); background: var(--bg-2); padding: 0.75rem 1.5rem; box-shadow: 0 0 1px var(--shadow-outer); }
    .logo-img { width: 2.5rem; height: 2.5rem; object-fit: contain; }
    .hero-title { font-size: 1.875rem; letter-spacing: 0.1em; }
    .grid { display: grid; gap: 1.5rem; }
    @media (min-width: 768px) { .grid { grid-template-columns: 1fr 320px; } }
    .card { border-radius: 1rem; background: var(--bg-2); box-shadow: inset 0 0 0 1px var(--white-08), 0 0 1px var(--shadow-outer); overflow: hidden; margin-bottom: 1.5rem; }
    .card-header { display: flex; align-items: center; justify-content: space-between; padding: 1rem 1.25rem; border-bottom: 1px solid var(--white-08); gap: 0.5rem; flex-wrap: wrap; }
    .badge { display: inline-flex; align-items: center; gap: 0.5rem; border-radius: 0.5rem; padding: 0.25rem 0.625rem; font-size: 0.75rem; box-shadow: inset 0 0 0 1px var(--white-08); background: var(--white-05); }
    .btn-row { display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap; }
    button { display: inline-flex; align-items: center; gap: 0.5rem; border-radius: 0.5rem; padding: 0.5rem 0.75rem; font-size: 0.875rem; cursor: pointer; border: none; background: transparent; color: var(--text); box-shadow: inset 0 0 0 1px var(--white-08); transition: background 0.15s; }
    button:hover { background: var(--white-05); }
    .card-body { padding: 1.25rem; display: flex; flex-direction: column; gap: 1rem; }
    .muted { color: var(--proto); font-size: 0.875rem; line-height: 1.6; }
    .url-row { border-radius: 0.5rem; box-shadow: inset 0 0 0 1px var(--white-08); background: rgba(10,10,10,0.6); padding: 0.75rem; }
    .url-label { font-size: 0.7rem; color: var(--proto); margin-bottom: 0.2rem; }
    .url-val { font-size: 0.8rem; word-break: break-all; }
    .ta-wrap { border-radius: 0.5rem; box-shadow: inset 0 0 0 1px var(--white-08); background: rgba(10,10,10,0.6); padding: 0.75rem; }
    .ta-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.5rem; }
    .ta-label { font-size: 0.75rem; color: var(--proto); }
    textarea { width: 100%; height: 8rem; resize: vertical; background: var(--bg-1); color: var(--text); border: 1px solid var(--white-08); border-radius: 0.5rem; padding: 0.75rem; font: 0.72rem/1.6 ui-monospace, SFMono-Regular, Menlo, monospace; outline: none; display: block; }
    textarea:focus { box-shadow: 0 0 0 2px var(--main); }
    .aside-card { border-radius: 1rem; background: var(--bg-2); box-shadow: inset 0 0 0 1px var(--white-08); padding: 1rem; display: flex; flex-direction: column; gap: 0.5rem; margin-bottom: 1rem; }
    .aside-title { font-size: 0.875rem; font-weight: 600; margin-bottom: 0.25rem; }
    .action-btn { display: flex; align-items: center; justify-content: space-between; border-radius: 0.5rem; padding: 0.5rem 0.75rem; font-size: 0.875rem; box-shadow: inset 0 0 0 1px var(--white-08); cursor: pointer; background: transparent; color: var(--text); border: none; width: 100%; transition: background 0.15s; text-align: left; }
    .action-btn:hover { background: var(--white-05); }
    .action-left { display: flex; align-items: center; gap: 0.5rem; }
    .dot { width: 0.5rem; height: 0.5rem; border-radius: 50%; background: var(--main); animation: pulse 2s infinite; flex-shrink: 0; }
    @keyframes pulse { 0%,100%{opacity:1}50%{opacity:0.5} }
    .status-row { display: flex; align-items: center; justify-content: space-between; border-radius: 0.5rem; padding: 0.5rem 0.75rem; box-shadow: inset 0 0 0 1px var(--white-08); }
    .status-left { display: flex; align-items: center; gap: 0.5rem; font-size: 0.875rem; }
    .stat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0.5rem; margin-top: 0.75rem; }
    .stat-cell { border-radius: 0.5rem; box-shadow: inset 0 0 0 1px var(--white-08); padding: 0.75rem; }
    .stat-label { font-size: 0.7rem; color: var(--proto); }
    .stat-val { font-size: 0.75rem; font-weight: 600; word-break: break-all; }
  `;
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>${escapeHtml(heading)}</title>
    <style>${css}</style>
  </head>
  <body>
    <main>
      <div class="hero">
        <div class="hero-badge">
          <img class="logo-img" src="${logoDataUri}" alt="Daydream" />
          <span class="hero-title">Something went wrong</span>
        </div>
      </div>
      <div class="grid">
        <div>
          <div class="card">
            <div class="card-header">
              <div class="badge">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3"/><path d="M12 9v4"/><path d="M12 17h.01"/></svg>
                ${escapeHtml(context.errorType.replace(/_/g,' '))}
              </div>
              <div class="btn-row">
                <button id="action-retry">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg>
                  Try again
                </button>
              </div>
            </div>
            <div class="card-body">
              <p class="muted">Daydream couldn&#39;t load this page. The site may be unavailable or the address may be incorrect.</p>
              ${context.originalUrl ? `<div class='url-row'><div class='url-label'>Requested URL</div><div class='url-val'>${escapeHtml(context.originalUrl)}</div></div>` : ''}
              <div class="ta-wrap">
                <div class="ta-top">
                  <span class="ta-label">Error details</span>
                  <button id="btn-copy" style="padding:0.2rem 0.5rem;font-size:0.7rem">Copy</button>
                </div>
                <textarea id="err-ta" readonly>${escapeHtml(detailLines)}</textarea>
              </div>
            </div>
          </div>
        </div>
        <div>
          <div class="aside-card">
            <div class="aside-title">Quick actions</div>
            <button class="action-btn" id="action-back">
              <span class="action-left">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m12 19-7-7 7-7"/><path d="M19 12H5"/></svg>
                Go back
              </span>
            </button>
          </div>
          <div class="aside-card">
            <div class="aside-title">Status</div>
            <div class="status-row">
              <div class="status-left"><div class="dot"></div><span>Client online</span></div>
            </div>
            <div class="stat-grid">
              <div class='stat-cell'><div class='stat-label'>Error type</div><div class='stat-val'>${escapeHtml(context.errorType)}</div></div>
              <div class='stat-cell'><div class='stat-label'>Request ID</div><div class='stat-val'>${escapeHtml(context.requestId)}</div></div>
            </div>
          </div>
        </div>
      </div>
    </main>
    <script>
      window.__ec = ${JSON.stringify(context).replace(/</g,'\u003c')};
      document.getElementById('action-retry').addEventListener('click',function(){
        var u=window.__ec.originalUrl;
        if(u)window.location.href=u;else window.location.reload();
      });
      document.getElementById('action-back').addEventListener('click',function(){
        window.history.back();
      });
      document.getElementById('btn-copy').addEventListener('click',function(){
        var ta=document.getElementById('err-ta');
        try{navigator.clipboard.writeText(ta.value);}catch(e){ta.select();document.execCommand('copy');}
      });
    </script>
  </body>
</html>`;
}


export async function installErrorPageSubsystem(
  controller: ControllerLike,
): Promise<void> {
  const renderInto = (
    frame: FrameWithElement,
    context: ErrorPageContext,
  ): void => {
    const iframe = frame.element;
    if (!iframe) return;
    try {
      iframe.dataset.errorContext = JSON.stringify(context);
      iframe.srcdoc = buildErrorDocument(context);
    } catch (err) {
      console.warn('[tabs/errorPlugin] failed to render error page:', err);
    }
  };

  const installOnFrame = (frame: unknown): void => {
    const f = frame as FrameWithElement;
    if (!f?.hooks?.fetch?.preresponse) return;
    try {
      const plugin = new DdxErrorPagePlugin((context) => renderInto(f, context));
      plugin.install(f as unknown as ErrorPluginFrameLike);
    } catch (err) {
      console.warn('[tabs/errorPlugin] plugin install failed for frame:', err);
    }
  };

  if (Array.isArray(controller.frames)) {
    for (const frame of controller.frames) installOnFrame(frame);
  }

  const original = controller.createFrame?.bind(controller);
  if (typeof original === 'function') {
    controller.createFrame = (...args: unknown[]) => {
      const frame = original(...args);
      if (frame) installOnFrame(frame);
      return frame;
    };
  }

  console.log('[tabs] error page subsystem installed');
}
